    out[y][x] = 5

    commands = {
        frozenset({(0,0),(0,1),(1,0),(1,2),(2,1)}): ("H", 2),
        frozenset({(0,0),(0,2),(1,0),(1,2),(2,0),(2,1),(2,2)}): ("H", -1),
        frozenset({(0,0),(0,2),(1,1),(2,1)}): ("V", 2),
        frozenset({(0,0),(0,1),(0,2),(1,1),(2,0),(2,2)}): ("H", -3),
    }
    bands = list(range(0, h, 4))
    sequence = []
    # Read the left column of panels top-to-bottom, then the right column.
    for c0 in (0, 4):
        for r0 in bands:
            cells = [(r-r0, c-c0) for r in range(r0, min(r0+3,h))
                     for c in range(c0, min(c0+3,sep)) if grid[r][c] not in (0,4,5)]
            if cells:
                sequence.append(commands[frozenset(cells)])

    for axis, move in sequence:
        if axis == "H":
            y += 1
            step = move
            # Reverse a horizontal command at the canvas edge rather than
            # allowing the encoded path to leave the output grid.
            if x + step < 0 or x + step >= out_w:
                step = -step
            end = x + step
            for c in range(min(x,end), max(x,end)+1):
