            color = None
            # Recover the panel's color from the corresponding source glyph.
            # A command's order identifies its panel in the column-major scan.
            # Find the matching occurrence by consuming it in the loop below.
            x = end
        else:
            for rr in range(y+1, min(h, y+move+1)):
                if 0 <= x < out_w:
                    out[rr][x] = 0
            y += move
    return out
